import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"35、【晋】 坤下离上","description":"周易口诀义 - 35、【晋】 坤下离上","frontmatter":{"title":"35、【晋】 坤下离上","description":"周易口诀义 - 35、【晋】 坤下离上"},"headers":[],"relativePath":"zh/classics/koujueyi/037.md","filePath":"zh/classics/koujueyi/037.md"}'),r={name:"zh/classics/koujueyi/037.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_35、【晋】-坤下离上" tabindex="-1">35、【晋】 坤下离上 <a class="header-anchor" href="#_35、【晋】-坤下离上" aria-label="Permalink to “35、【晋】 坤下离上”">​</a></h1><p>彖曰：晋，进也。明出地上，顺而丽乎大明，柔进而上行，是以「康侯用锡马蕃庶，昼日三接」也。</p><p>象曰：明出地上，晋。君子以自昭明德。</p><p>初六：晋如摧如，贞吉。罔孚，裕无咎。</p><p>象曰：「晋如摧如」，独行正也。「裕无咎」，未受命也。</p><p>六二：晋如愁如，贞吉。受兹介福，于其王母。</p><p>象曰：「受兹介福」，以中正也。</p><p>六三：众允，悔亡。</p><p>象曰：众允之志，上行也。</p><p>九四：晋如鼫鼠，贞厉。</p><p>象曰：鼫鼠贞厉，位不当也。</p><p>六五：悔亡，失得勿恤，往吉，无不利。</p><p>象曰：「失得勿恤」，往有庆也。</p><p>上九：晋其角，维用伐邑，厉吉无咎，贞吝。</p><p>象曰：「维用伐邑」，道未光也。</p><p>无（四库全书标明，摘录时缺豫、随、无妄、大壮、晋、睽、蹇、解、中孚八卦）</p>',16)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
